class Point {
    protected int x, y;
    public Point(int x, int y) { this.x = x; this.y = y; }

    // Using instanceof allows subclasses to match
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Point)) return false; // Pitfall!
        Point other = (Point) obj;
        return this.x == other.x && this.y == other.y;
    }
}

class ColorPoint extends Point {
    private String color;
    public ColorPoint(int x, int y, String color) {
        super(x, y);
        this.color = color;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof ColorPoint)) return false;
        ColorPoint other = (ColorPoint) obj;
        return super.equals(obj) && this.color.equals(other.color);
    }
}

public class AsymmetryDemo {
    public static void main(String[] args) {
        Point p = new Point(1, 2);
        ColorPoint cp = new ColorPoint(1, 2, "RED");

        System.out.println("p.equals(cp):  " + p.equals(cp));  // true! (Point ignores color)
        System.out.println("cp.equals(p):  " + cp.equals(p));  // false! (ColorPoint requires ColorPoint)
        System.out.println("SYMMETRY VIOLATED: " + (p.equals(cp) != cp.equals(p)));
    }
}

