import java.util.Objects;

class UserProfile {
    private String username; // May be null
    private String email;    // May be null

    public UserProfile(String username, String email) {
        this.username = username;
        this.email = email;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        UserProfile other = (UserProfile) obj;

        // Completely safe even if username or email is null
        return Objects.equals(this.username, other.username) &&
               Objects.equals(this.email, other.email);
    }

    @Override
    public int hashCode() {
        return Objects.hash(username, email);
    }
}

public class HardenedEqualsDemo {
    public static void main(String[] args) {
        UserProfile u1 = new UserProfile(null, "test@corp.com");
        UserProfile u2 = new UserProfile(null, "test@corp.com");
        UserProfile u3 = new UserProfile("admin", null);

        System.out.println("u1.equals(u2): " + u1.equals(u2)); // true! No NPE
        System.out.println("u1.equals(u3): " + u1.equals(u3)); // false! No NPE
        System.out.println("u1.equals(null): " + u1.equals(null)); // false! No NPE
    }
}

