import java.util.Objects;

class BaseToken {
    protected String tokenId;
    public BaseToken(String tokenId) {
        this.tokenId = tokenId;
    }
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        BaseToken other = (BaseToken) obj;
        return Objects.equals(tokenId, other.tokenId);
    }
    @Override
    public int hashCode() {
        return Objects.hash(tokenId);
    }
}

class ExpiringToken extends BaseToken {
    private long expiryTimestamp;
    public ExpiringToken(String tokenId, long expiry) {
        super(tokenId);
        this.expiryTimestamp = expiry;
    }
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        ExpiringToken other = (ExpiringToken) obj;
        return Objects.equals(tokenId, other.tokenId) && expiryTimestamp == other.expiryTimestamp;
    }
    @Override
    public int hashCode() {
        return Objects.hash(tokenId, expiryTimestamp);
    }
}

public class SymmetryApp {
    public static void main(String[] args) {
        BaseToken base = new BaseToken("T100");
        ExpiringToken expiring = new ExpiringToken("T100", 5000L);

        System.out.println("base.equals(expiring): " + base.equals(expiring));
        System.out.println("expiring.equals(base): " + expiring.equals(base));
    }
}

class InterestRate {
    private double annualPercentageRate;
    public InterestRate(double rate) {
        this.annualPercentageRate = rate;
    }
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        InterestRate other = (InterestRate) obj;
        return Double.compare(this.annualPercentageRate, other.annualPercentageRate) == 0;
    }
    @Override
    public int hashCode() {
        return Double.hashCode(annualPercentageRate);
    }
}

public class FloatEqualityApp {
    public static void main(String[] args) {
        InterestRate r1 = new InterestRate(Double.NaN);
        InterestRate r2 = new InterestRate(Double.NaN);
        System.out.println("NaN rates equal: " + r1.equals(r2));

        InterestRate r3 = new InterestRate(0.0);
        InterestRate r4 = new InterestRate(-0.0);
        System.out.println("Positive vs Negative zero equal: " + r3.equals(r4));
    }
}

