class CustomerKey {
    private int tenantId;
    private String customerCode;

    public CustomerKey(int tenantId, String code) {
        this.tenantId = tenantId;
        this.customerCode = code;
    }

    // BUG: Parameter is CustomerKey instead of Object! Accidental overload!
