    public static void main(String[] args) {
        Set<CustomerKey> keys = new HashSet<>();
        keys.add(new CustomerKey(1, "CUST-A"));

        CustomerKey query = new CustomerKey(1, "CUST-A");
        System.out.println("Query in set: " + keys.contains(query));
    }
}

