import java.util.Arrays;
import java.util.Objects;

class AuditRecord {
    private final String recordId;
    private final double transactionAmount;
    private final String[] tags;
    private final String metadata;

    public AuditRecord(String id, double amt, String[] tags, String meta) {
        this.recordId = id;
        this.transactionAmount = amt;
        this.tags = tags;
        this.metadata = meta;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        AuditRecord other = (AuditRecord) obj;
        return Objects.equals(recordId, other.recordId) &&
               Double.compare(transactionAmount, other.transactionAmount) == 0 &&
               Arrays.equals(tags, other.tags) &&
               Objects.equals(metadata, other.metadata);
    }

    @Override
    public int hashCode() {
        return Objects.hash(recordId, transactionAmount, Arrays.hashCode(tags), metadata);
    }
}

public class AuditApp {
    public static void main(String[] args) {
        AuditRecord r1 = new AuditRecord("REC-1", 150.0, new String[]{"finance", "q4"}, null);
        AuditRecord r2 = new AuditRecord("REC-1", 150.0, new String[]{"finance", "q4"}, null);
        AuditRecord r3 = new AuditRecord("REC-1", 150.0, new String[]{"audit"}, null);

        System.out.println(r1.equals(r2));
        System.out.println(r1.equals(r3));
        System.out.println(r1.equals(null));
        System.out.println(r1.hashCode() == r2.hashCode());
    }
}
